mapper.select:
SELECT * FROM (
    SELECT a.*, ROWNUM AS rn FROM (
        SELECT * FROM TBL_BANK_INTERFACE_CONFIG

            DELETE_FLAG = 0

                AND BANK_CODE LIKE CONCAT('%', #{interfaceCode}, '%')


                AND BANK_NAME LIKE CONCAT('%', #{interfaceName}, '%')


                AND BANK_NAME LIKE CONCAT('%', #{bankName}, '%')


                AND BANK_CODE = #{bankCode}


                AND INTERFACE_TYPE = #{interfaceType}


                AND IS_ENABLED = #{isEnabled}


                AND LAST_CONNECT_STATUS = #{lastConnectStatus}


                AND ORG_ID = #{orgId}


                AND CREATE_TIME >= #{beginTime}


                AND CREATE_TIME <= #{endTime}


        ORDER BY PRIORITY DESC, CREATE_TIME DESC
    ) a
) WHERE rn > #{offset} AND rn <= (#{offset} + #{limit})

SELECT COUNT(*) FROM TBL_BANK_INTERFACE_CONFIG

    DELETE_FLAG = 0

        AND BANK_CODE LIKE CONCAT('%', #{interfaceCode}, '%')


        AND BANK_NAME LIKE CONCAT('%', #{interfaceName}, '%')


        AND BANK_NAME LIKE CONCAT('%', #{bankName}, '%')


        AND BANK_CODE = #{bankCode}


        AND INTERFACE_TYPE = #{interfaceType}


        AND IS_ENABLED = #{isEnabled}


        AND LAST_CONNECT_STATUS = #{lastConnectStatus}


        AND ORG_ID = #{orgId}

SELECT * FROM TBL_BANK_INTERFACE_CONFIG

    DELETE_FLAG = 0
    AND IS_ENABLED = 1
    AND LAST_CONNECT_STATUS = 'SUCCESS'

        AND BANK_CODE = #{bankCode}


        AND INTERFACE_TYPE = #{interfaceType}


        AND ORG_ID = #{orgId}


ORDER BY PRIORITY DESC, LOAD_BALANCE_WEIGHT DESC
